using System;using System.Collections.Generic;public class RBSTNode<T> where T : IComparable<T>{public T Value;public RBSTNode<T> Left;public RBSTNode<T> Right;public int Size;public int Priority;public RBSTNode(T value){Value = value;Left = null;Right = null;Size = 1;Priority = new Random().Next();}}public class SelfBalancingRBST<T> where T : IComparable<T>{private RBSTNode<T> root;private int Size(RBSTNode<T> node){return node == null ? 0 : node.Size;}private void UpdateSize(RBSTNode<T> node){if(node != null){node.Size = Size(node.Left) + Size(node.Right) + 1;}}private RBSTNode<T> RotateRight(RBSTNode<T> node){RBSTNode<T> newRoot = node.Left;node.Left = newRoot.Right;newRoot.Right = node;UpdateSize(node);UpdateSize(newRoot);return newRoot;}private RBSTNode<T> RotateLeft(RBSTNode<T> node){RBSTNode<T> newRoot = node.Right;node.Right = newRoot.Left;newRoot.Left = node;UpdateSize(node);UpdateSize(newRoot);return newRoot;}private RBSTNode<T> Balance(RBSTNode<T> node){if(node == null)return null;if(Size(node.Left) > Size(node.Right) + 1){if(Size(node.Left.Right) > Size(node.Left.Left)){node.Left = RotateLeft(node.Left);}node = RotateRight(node);}else if(Size(node.Right) > Size(node.Left) + 1){if(Size(node.Right.Left) > Size(node.Right.Right)){node.Right = RotateRight(node.Right);}node = RotateLeft(node);}UpdateSize(node);return node;}public void Insert(T value){root = Insert(root, value);}private RBSTNode<T> Insert(RBSTNode<T> node, T value){if(node == null)return new RBSTNode<T>(value);if(value.CompareTo(node.Value) < 0){node.Left = Insert(node.Left, value);}else if(value.CompareTo(node.Value) > 0){node.Right = Insert(node.Right, value);}UpdateSize(node);return Balance(node);}public void Delete(T value){root = Delete(root, value);}private RBSTNode<T> Delete(RBSTNode<T> node, T value){if(node == null)return null;if(value.CompareTo(node.Value) < 0){node.Left = Delete(node.Left, value);}else if(value.CompareTo(node.Value) > 0){node.Right = Delete(node.Right, value);}else{if(node.Left == null)return node.Right;if(node.Right == null)return node.Left;RBSTNode<T> minLargerNode = GetMin(node.Right);node.Value = minLargerNode.Value;node.Right = Delete(node.Right, minLargerNode.Value);}UpdateSize(node);return Balance(node);}private RBSTNode<T> GetMin(RBSTNode<T> node){while(node.Left != null)node = node.Left;return node;}public bool Search(T value){return Search(root, value);}private bool Search(RBSTNode<T> node, T value){if(node == null)return false;if(value.CompareTo(node.Value) == 0)return true;if(value.CompareTo(node.Value) < 0)return Search(node.Left, value);return Search(node.Right, value);}public List<T> InOrderTraversal(){List<T> result = new List<T>();InOrderTraversal(root, result);return result;}private void InOrderTraversal(RBSTNode<T> node, List<T> result){if(node != null){InOrderTraversal(node.Left, result);result.Add(node.Value);InOrderTraversal(node.Right, result);}}}